<?php
declare(strict_types=1);
require_once __DIR__.'/../config/salad-monitor.php';
function expect(bool $ok,string $message): void {if(!$ok)throw new RuntimeException($message);}
$sample=[['time'=>'2026-10-07T18:00:00Z','text_log'=>"\e[32m#0 RTX 4070 Ti SUPER 161.58 TH/s 284.8W 0.567 73% 69C\e[0m"],['time'=>'2026-10-07T17:59:00Z','text_log'=>'15 min 161.64 TH/s'],['time'=>'2026-10-07T17:58:00Z','text_log'=>'Shares accepted 16 rejected 0 HW errors 0']];
$m=hache_salad_monitor_parse($sample);expect($m['gpu']==='RTX 4070 Ti SUPER','GPU no extraída');expect($m['hashrate_ths']===161.58,'TH/s actual no extraído');expect($m['hashrate_15m_ths']===161.64,'TH/s 15 min no extraído');expect($m['watts']===284.8&&$m['temperature_c']===69&&$m['fan_percent']===73,'Métricas de GPU no extraídas');expect($m['shares']['accepted']===16,'Shares no extraídas');expect(hache_salad_monitor_status('running',$m)==='green','Estado sano incorrecto');$m['temperature_c']=84;expect(hache_salad_monitor_status('running',$m)==='yellow','Estado térmico incorrecto');expect(hache_salad_monitor_status('deploying',$m)==='red','Estado de grupo incorrecto');echo "SALAD_MONITOR_REGRESSION_OK\n";
$yellow=['group'=>'simulation-4070','health'=>'yellow','metrics'=>$m];$notifications=0;$notify=static function(array $group)use(&$notifications):bool{$notifications++;return true;};$first=hache_salad_monitor_apply_alert_transitions([$yellow],[],$notify);expect($first['sent']===1&&$notifications===1,'La primera entrada en amarillo debe alertar');$second=hache_salad_monitor_apply_alert_transitions([$yellow],$first['state'],$notify);expect($second['sent']===0&&$notifications===1,'No debe duplicar alerta mientras siga amarillo');$green=$yellow;$green['health']='green';$recovered=hache_salad_monitor_apply_alert_transitions([$green],$second['state'],$notify);expect($recovered['sent']===0&&$notifications===1,'La recuperación no debe alertar');$again=hache_salad_monitor_apply_alert_transitions([$yellow],$recovered['state'],$notify);expect($again['sent']===1&&$notifications===2,'Debe alertar de nuevo al volver a amarillo');echo "SALAD_MONITOR_REGRESSION_OK\n";
